import dis, sys
import pybamm
from pybamm.expression_tree import binary_operators

tracked = {"l_left","l_right","left","out","r_left","r_right","right"}

pairs=[]
last_def={}
ops=[]

def tracer(frame, event, arg):
    if event == 'call' and frame.f_code is binary_operators.divide.__code__:
        frame.f_trace_opcodes = True
        return tracer
    if frame.f_code is not binary_operators.divide.__code__:
        return tracer
    if event == 'opcode':
        code = frame.f_code.co_code
        i = frame.f_lasti
        op = code[i]
        opname = dis.opname[op]
        oparg = code[i+1] if i+1 < len(code) else None
        if opname in ('LOAD_FAST','STORE_FAST'):
            name = frame.f_code.co_varnames[oparg]
            if name in tracked:
                lineno = frame.f_lineno
                ops.append((opname,name,lineno))
                if opname == 'STORE_FAST':
                    last_def[name]=lineno
                else:
                    if name in last_def:
                        pairs.append((name,last_def[name],lineno))
    return tracer

shared = pybamm.Addition(pybamm.Variable('a'), pybamm.Scalar(2))
tail = pybamm.Subtraction(pybamm.Variable('b'), pybamm.Variable('c'))
left = pybamm.Multiplication(shared, tail)

sys.settrace(tracer)
try:
    binary_operators.divide(left, shared)
finally:
    sys.settrace(None)

print('OPS')
for o in ops:
    print(o)
print('PAIRS')
for p in sorted(set(pairs)):
    print(p)
